create or replace function public.validate_profile_creation_attribution() returns trigger language plpgsql security definer set search_path = '' as $function$ begin if not public.has_role('admin'::public.app_role) and not public.has_role('super_admin'::public.app_role) then if new.organization_id is not null then raise exception 'Unauthorized: organization assignment must be performed by authorized staff'; end if; if new.status is distinct from 'active' then raise exception 'Unauthorized: invalid profile status'; end if; if new.lifecycle_stage is distinct from 'Registered User' then raise exception 'Unauthorized: invalid profile lifecycle stage'; end if; if new.source_initiative_id is not null and not exists (select 1 from public.initiatives i where i.id=new.source_initiative_id and i.is_approved=true and i.is_published=true and coalesce(i.is_impact_pool,false)=false) then raise exception 'Invalid source initiative'; end if; if new.primary_initiative_id is not null and not exists (select 1 from public.initiatives i where i.id=new.primary_initiative_id and i.is_approved=true and i.is_published=true and coalesce(i.is_impact_pool,false)=false) then raise exception 'Invalid primary initiative'; end if; end if; return new; end; $function$; drop trigger if exists trg_validate_profile_creation_attribution on public.profiles; create trigger trg_validate_profile_creation_attribution before insert on public.profiles for each row execute function public.validate_profile_creation_attribution(); revoke all on function public.validate_profile_creation_attribution() from public,anon,authenticated,service_role; grant execute on function public.validate_profile_creation_attribution() to postgres;
